parameters.jsCode:
// Normalizar payload de error o resultado de healthcheck
const item = $input.item.json;
const isCron = !!item.timestamp;

let restaurantId = item.body?.restaurantId || item.restaurantId || 'SISTEMA_GLOBAL';
let action = item.body?.action || item.action || 'AUDIT_HEALTHCHECK';
let details = item.body?.details || item.details || 'Verificación periódica de flujos web';
let errorStack = item.body?.errorStack || item.errorStack || '';
let category = item.body?.category || item.category || 'SYSTEM_EVENT';
let isCritical = category === 'ERROR_CRITICAL' || errorStack.length > 0;

return {
  json: {
    isCron,
    isCritical,
    restaurantId,
    action,
    details,
    category,
    errorStack,
    timestamp: new Date().toISOString()
  }
};

